// gegeneinander laufen und API-Guthaben verbrennen.

const MAX_VERSUCHE = 2;

const store = $getWorkflowStaticData('node');
const execId = String($execution.id);

// Bei jedem neuen Workflow-Lauf den Speicher komplett leeren
if (store.execId !== execId) {
  for (const k of Object.keys(store)) { delete store[k]; }
  store.execId = execId;
}

// Kapitel eindeutig identifizieren
