// Wandelt literale Bullet-Zeichen (•) in echte Markdown-Listen um.
// Ohne diesen Schritt verschmelzen alle Stichpunkte zu einem Fliesstext-Absatz,
// weil Markdown einen einzelnen Zeilenumbruch als Leerzeichen behandelt
// und '•' kein gueltiger Listen-Marker ist.

function normalisieren(md) {
  if (typeof md !== 'string' || !md) return md;
  let t = md.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

  // 1. Bullet-Zeichen, die mitten in einer Zeile stehen, auf eigene Zeile ziehen
  t = t.replace(/([^\n])[ \t]*([•·▪●‣⁃◦])[ \t]+/g, '$1\n$2 ');

  // 2. Bullet-Zeichen am Zeilenanfang in echte Markdown-Listenpunkte wandeln
  t = t.replace(/^[ \t]*[•·▪●‣⁃◦][ \t]*/gm, '- ');

  const istItem = (z) => /^\s*(?:[-*+]|\d{1,2}\.)\s+\S/.test(z);

  // 3. Leerzeile VOR dem ersten Listenpunkt eines Blocks erzwingen
  const zeilen = t.split('\n');
  const raus = [];
  for (const z of zeilen) {
    const vorher = raus.length ? raus[raus.length - 1] : '';
    if (istItem(z) && vorher.trim() !== '' && !istItem(vorher)) raus.push('');
    raus.push(z);
  }
  t = raus.join('\n');

  // 4. Leerzeile NACH dem letzten Listenpunkt eines Blocks erzwingen
  const z2 = t.split('\n');
  const raus2 = [];
  for (let i = 0; i < z2.length; i++) {
    raus2.push(z2[i]);
    const naechste = z2[i + 1];
    if (istItem(z2[i]) && naechste !== undefined && naechste.trim() !== '' && !istItem(naechste)) raus2.push('');
  }
  t = raus2.join('\n');

  // 5. Uebermaessige Leerzeilen zusammenfassen
  t = t.replace(/\n{5,}/g, '\n\n\n\n');

  return t;
}

for (const item of $input.all()) {
  if (typeof item.json.fertiges_Buch === 'string') {
    const vorher = (item.json.fertiges_Buch.match(/[•·▪●‣⁃◦]/g) || []).length;
    item.json.fertiges_Buch = normalisieren(item.json.fertiges_Buch);
    item.json.bullets_umgewandelt = vorher;
