// Ersetzt {{BUCH_TITEL}}, {{BUCH_UNTERTITEL}}, {{BUCH_AUTOR}} und die
// Kontaktadresse in der Titelei-DOCX.
// Noetig, weil CloudConvert kein Templating nach DOCX kann und Word die
// Platzhalter ueber mehrere Runs zerreisst. Das ZIP wird ohne Kompression
// neu gebaut (zlib ist in n8n Code-Nodes gesperrt) - Word und LibreOffice
// lesen solche DOCX problemlos.

const eingabe = $input.first();
const quelle = $('Input').first().json;

// Kontaktadresse = Initialen des Pseudonyms, klein, @example.com
// Pseudonym A -> pa@example.com | Pseudonym B -> pb@example.com | Pseudonym C -> pc@example.com
function mailAus(autor) {
  const teile = String(autor == null ? '' : autor).split(/\s+/).filter(Boolean);
  const initialen = teile
    .map(function (t) { return t.replace(/[^A-Za-zÄÖÜäöüß]/g, '').charAt(0); })
    .filter(Boolean).join('').toLowerCase();
  return initialen ? initialen + '@example.com' : '';
}

const mail = mailAus(quelle.autor);

const map = {
  BUCH_TITEL: quelle.titel,
  BUCH_UNTERTITEL: quelle.untertitel,
  BUCH_AUTOR: quelle.autor,
  BUCH_KONTAKT: mail
};

function xmlEscape(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function ersetzeInAbsaetzen(xml, map, mail) {
  let treffer = 0;
  const neuXml = xml.replace(/<w:p(?:\s[^>]*)?>[\s\S]*?<\/w:p>/g, (absatz) => {
    const teile = [];
    const re = /(<w:t(?:\s[^>]*)?>)([\s\S]*?)(<\/w:t>)/g;
    let m;
    while ((m = re.exec(absatz)) !== null) {
      teile.push({ start: m.index, ende: re.lastIndex, oeffner: m[1], text: m[2], schliesser: m[3] });
    }
    if (!teile.length) return absatz;
    const gesamt = teile.map(t => t.text).join('');
    if (gesamt.indexOf('{{') === -1 && gesamt.toUpperCase().indexOf('XXX@') === -1) return absatz;

    let neu = gesamt;
    neu = neu.split('{{BUCH_AUTOR}}]').join(xmlEscape(map.BUCH_AUTOR));
    for (const k of Object.keys(map)) {
      neu = neu.split('{{' + k + '}}').join(xmlEscape(map[k]));
    }
    if (mail) neu = neu.replace(/XXX@example\.com/gi, mail);
    if (neu === gesamt) return absatz;
    treffer++;

    const ausgabe = [];
    let pos = 0;
    teile.forEach((t, i) => {
      ausgabe.push(absatz.slice(pos, t.start));
      let oeffner = t.oeffner;
      let inhalt = '';
      if (i === 0) {
        inhalt = neu;
        if (!/xml:space=/.test(oeffner)) oeffner = oeffner.replace(/^<w:t/, '<w:t xml:space="preserve"');
