  const lokale = [], zentrale = [];
  let offset = 0;
  const zeit = 0, datum = (26 << 9) | (1 << 5) | 1;
  for (const e of eintraege) {
    const name = Buffer.from(e.pfad, 'utf8');
    const daten = e.buf;
    const crc = crc32(daten);
    const lh = Buffer.alloc(30);
    lh.writeUInt32LE(0x04034b50, 0); lh.writeUInt16LE(20, 4); lh.writeUInt16LE(0, 6);
    lh.writeUInt16LE(0, 8); lh.writeUInt16LE(zeit, 10); lh.writeUInt16LE(datum, 12);
    lh.writeUInt32LE(crc, 14); lh.writeUInt32LE(daten.length, 18); lh.writeUInt32LE(daten.length, 22);
    lh.writeUInt16LE(name.length, 26); lh.writeUInt16LE(0, 28);
    lokale.push(lh, name, daten);
    const ch = Buffer.alloc(46);
    ch.writeUInt32LE(0x02014b50, 0); ch.writeUInt16LE(20, 4); ch.writeUInt16LE(20, 6);
    ch.writeUInt16LE(0, 8); ch.writeUInt16LE(0, 10); ch.writeUInt16LE(zeit, 12); ch.writeUInt16LE(datum, 14);
    ch.writeUInt32LE(crc, 16); ch.writeUInt32LE(daten.length, 20); ch.writeUInt32LE(daten.length, 24);
    ch.writeUInt16LE(name.length, 28); ch.writeUInt16LE(0, 30); ch.writeUInt16LE(0, 32);
    ch.writeUInt16LE(0, 34); ch.writeUInt16LE(0, 36); ch.writeUInt32LE(0, 38); ch.writeUInt32LE(offset, 42);
    zentrale.push(ch, name);
    offset += 30 + name.length + daten.length;
  }
  const zBuf = Buffer.concat(zentrale);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0); eocd.writeUInt16LE(0, 4); eocd.writeUInt16LE(0, 6);
  eocd.writeUInt16LE(eintraege.length, 8); eocd.writeUInt16LE(eintraege.length, 10);
  eocd.writeUInt32LE(zBuf.length, 12); eocd.writeUInt32LE(offset, 16); eocd.writeUInt16LE(0, 20);
  return Buffer.concat([...lokale, zBuf, eocd]);
}

const eintraege = [];
let treffer = 0;
let gefunden = false;

for (const key of Object.keys(eingabe.binary || {})) {
  const b = eingabe.binary[key];
  const pfad = (b.directory ? b.directory + '/' : '') + b.fileName;
  let buf = await this.helpers.getBinaryDataBuffer(0, key);
  if (pfad === 'word/document.xml') {
    gefunden = true;
    const r = ersetzeInAbsaetzen(buf.toString('utf8'), map, mail);
    treffer = r.treffer;
    buf = Buffer.from(r.xml, 'utf8');
