    ch.writeUInt16LE(name.length, 28); ch.writeUInt16LE(0, 30); ch.writeUInt16LE(0, 32);
    ch.writeUInt16LE(0, 34); ch.writeUInt16LE(0, 36); ch.writeUInt32LE(0, 38); ch.writeUInt32LE(offset, 42);
    zentrale.push(ch, name);
    offset += 30 + name.length + daten.length;
  }
  const zBuf = Buffer.concat(zentrale);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0); eocd.writeUInt16LE(0, 4); eocd.writeUInt16LE(0, 6);
  eocd.writeUInt16LE(eintraege.length, 8); eocd.writeUInt16LE(eintraege.length, 10);
  eocd.writeUInt32LE(zBuf.length, 12); eocd.writeUInt32LE(offset, 16); eocd.writeUInt16LE(0, 20);
  return Buffer.concat([...lokale, zBuf, eocd]);
}

const eintraege = [];
let treffer = 0;
let gefunden = false;

for (const key of Object.keys(eingabe.binary || {})) {
  const b = eingabe.binary[key];
  const pfad = (b.directory ? b.directory + '/' : '') + b.fileName;
  let buf = await this.helpers.getBinaryDataBuffer(0, key);
  if (pfad === 'word/document.xml') {
    gefunden = true;
    const r = ersetzeInAbsaetzen(buf.toString('utf8'), map, mail);
    treffer = r.treffer;
    buf = Buffer.from(r.xml, 'utf8');
  }
  eintraege.push({ pfad, buf });
}

if (!gefunden) throw new Error('word/document.xml nicht im Archiv gefunden');

const zip = zipSchreiben(eintraege);
const bin = await this.helpers.prepareBinaryData(zip, 'titelei.docx', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document');

return [{ json: { ersetzte_absaetze: treffer, kontakt: mail, dateien: eintraege.length, bytes: zip.length }, binary: { data: bin } }];
